package evidence

import (
	"github.com/LLM-4-People/mailsense/internal/locale"
	"github.com/LLM-4-People/mailsense/internal/mail"
	"github.com/LLM-4-People/mailsense/internal/psl"
	"github.com/LLM-4-People/mailsense/internal/threads"
)

// Pinned data a signal reads (Signal.Data): its digest is part of the
// signal's effective version, so data regenerated by a scripts/update-*.sh
// recomputes exactly the signals that read it.
const (
	DataLocale = "locale" // internal/locale: CLDR names and patterns, UDHR profiles, currencies, UTS #39 confusables
	DataMail   = "mail"   // internal/mail: scripts, folding, body cleaning, message kinds, subject prefixes, question marks
	DataPSL    = "psl"    // the Public Suffix List (registrable domains, organisations)
	// DataThreads: the rules of internal/threads (conversations, reply
	// matching, histories): code, versioned by threads.Version.
	DataThreads = "threads"
)

// dataDigest is the digest of one pinned data name (false: unknown name).
func dataDigest(name string) (string, bool) {
	switch name {
	case DataLocale:
		return locale.DataDigest(), true
	case DataMail:
		return mail.DataDigest(), true
	case DataPSL:
		return psl.DataDigest(), true
	case DataThreads:
		return threads.Version, true
	}
	return "", false
}

// textData are the data of a signal of the message's own text (cleaned,
// folded, its language's patterns).
func textData() []string { return []string{DataMail, DataLocale} }

// contextData are the data of a thread or history signal (conversations:
// subject prefixes and kinds; organisations: registrable domains; the
// threading rules themselves).
func contextData() []string { return []string{DataMail, DataPSL, DataThreads} }
